+'use client';
+
+import { HexAlphaColorPicker } from 'react-colorful';
+
+import {
+  Popover,
+  PopoverContent,
+  PopoverTrigger
+} from '@/components/ui/popover';
+
+type CompactColorSwatchProps = {
+  value: string;
+  onChange: (color: string) => void;
+};
+
+export function CompactColorSwatch({
+  value,
+  onChange
+}: CompactColorSwatchProps) {
+  return (
+    <Popover>
+      <PopoverTrigger asChild>
+        <button
+          className="h-7 w-7 rounded border border-input overflow-hidden shrink-0 cursor-pointer"
+          style={{ backgroundColor: value }}
+        />
+      </PopoverTrigger>
+      <PopoverContent className="w-auto p-3" side="bottom" align="center">
+        <HexAlphaColorPicker color={value} onChange={onChange} />
+      </PopoverContent>
+    </Popover>
+  );
+}
