diff --git a/components/canvas/konva/text-v2-node.tsx b/components/canvas/konva/text-v2-node.tsx
new file mode 100644
index 0000000..31ddbf2
--- /dev/null
+++ b/components/canvas/konva/text-v2-node.tsx
@@ -0,0 +1,287 @@
+'use client';
+
+import React, { useCallback, useEffect, useRef } from 'react';
+import { Group, Rect, Text, Transformer } from 'react-konva';
+import Konva from 'konva';
+
+import { TextV2Object } from '../types';
+
+const getFontStyle = (isBold: boolean, isItalic: boolean): string => {
+  const fontStyles: string[] = [];
+  if (isBold) fontStyles.push('bold');
+  if (isItalic) fontStyles.push('italic');
+  if (fontStyles.length === 0) return 'normal';
+  return fontStyles.join(' ');
+};
+
+type TextV2NodeProps = {
+  textV2: TextV2Object;
+  isSelected: boolean;
+  isMultiSelect: boolean;
+  isEditing?: boolean;
+  draggable: boolean;
+  showTransformer: boolean;
+  opacity?: number;
+  onClick?: (e: Konva.KonvaEventObject<MouseEvent>) => void;
+  onDblClick?: (e: Konva.KonvaEventObject<MouseEvent>) => void;
+  onDragStart?: (e: Konva.KonvaEventObject<DragEvent>) => void;
+  onDragMove?: (e: Konva.KonvaEventObject<DragEvent>) => void;
+  onDragEnd?: (e: Konva.KonvaEventObject<DragEvent>) => void;
+  onTransformEnd?: (e: Konva.KonvaEventObject<Event>) => void;
+};
+
+const TextV2Node = ({
+  textV2,
+  isSelected,
+  isMultiSelect,
+  isEditing = false,
+  draggable,
+  showTransformer,
+  opacity = 1,
+  onClick,
+  onDblClick,
+  onDragStart,
+  onDragMove,
+  onDragEnd,
+  onTransformEnd
+}: TextV2NodeProps) => {
+  const groupRef = useRef<Konva.Group>(null);
+  const textRef = useRef<Konva.Text>(null);
+  const hitRectRef = useRef<Konva.Rect>(null);
+  const transformerRef = useRef<Konva.Transformer>(null);
+
+  useEffect(() => {
+    if (!showTransformer || !transformerRef.current || !groupRef.current)
+      return;
+    transformerRef.current.nodes([groupRef.current]);
+    transformerRef.current.getLayer()?.batchDraw();
+  }, [showTransformer, isSelected]);
+
+  const {
+    id,
+    text,
+    position,
+    width,
+    height,
+    fontSize,
+    fontFamily,
+    textColor,
+    textAlign = 'left',
+    isBold,
+    isItalic,
+    isUnderline,
+    padding = 4,
+    lineHeight = 1.2,
+    letterSpacing = 0,
+    rotation = 0,
+    scaleX = 1,
+    scaleY = 1
+  } = textV2;
+
+  // During side-anchor drags, counter-scale the Text child so it doesn't
+  // visually distort, and expand its width/height to fill the scaled container.
+  // Corner drags are handled by boundBoxFunc (uniform ratio) — no interference here.
+  const handleTransform = useCallback(() => {
+    const node = groupRef.current;
+    const textNode = textRef.current;
+    const hitRect = hitRectRef.current;
+    if (!node) return;
+
+    const sx = node.scaleX();
+    const sy = node.scaleY();
+
+    // Side drag: one axis stays ~1 while the other changes
+    const isSideDrag =
+      (Math.abs(sx - 1) < 0.001 && Math.abs(sy - 1) >= 0.001) ||
+      (Math.abs(sy - 1) < 0.001 && Math.abs(sx - 1) >= 0.001);
+
+    if (isSideDrag && textNode) {
+      // Counter-scale the Text so it renders at original size
+      // while the Group stretches around it
+      const invSx = 1 / Math.abs(sx);
+      const invSy = 1 / Math.abs(sy);
+      textNode.scaleX(invSx);
+      textNode.scaleY(invSy);
+      // Expand Text's layout dimensions so it fills the scaled container
+      textNode.width(node.width() * Math.abs(sx));
+      textNode.height(node.height() * Math.abs(sy));
+      if (hitRect) {
+        hitRect.scaleX(invSx);
+        hitRect.scaleY(invSy);
+        hitRect.width(node.width() * Math.abs(sx));
+        hitRect.height(node.height() * Math.abs(sy));
+      }
+    } else if (textNode) {
+      // Corner drag: reset any leftover counter-scale from a previous side drag
+      textNode.scaleX(1);
+      textNode.scaleY(1);
+      textNode.width(node.width());
+      textNode.height(node.height());
+      if (hitRect) {
+        hitRect.scaleX(1);
+        hitRect.scaleY(1);
+        hitRect.width(node.width());
+        hitRect.height(node.height());
+      }
+    }
+  }, []);
+
+  // Reset counter-scale on children after transform completes,
+  // so they return to normal before the next React render applies new props
+  const handleTransformEnd = useCallback(
+    (e: Konva.KonvaEventObject<Event>) => {
+      const textNode = textRef.current;
+      const hitRect = hitRectRef.current;
+      if (textNode) {
+        textNode.scaleX(1);
+        textNode.scaleY(1);
+      }
+      if (hitRect) {
+        hitRect.scaleX(1);
+        hitRect.scaleY(1);
+      }
+      onTransformEnd?.(e);
+    },
+    [onTransformEnd]
+  );
+
+  return (
+    <>
+      <Group
+        ref={groupRef}
+        id={id}
+        x={position.x}
+        y={position.y}
+        width={width}
+        height={height}
+        rotation={rotation}
+        scaleX={scaleX}
+        scaleY={scaleY}
+        draggable={draggable && !isEditing}
+        onClick={onClick}
+        onTap={onClick}
+        onDblClick={onDblClick}
+        onDblTap={onDblClick}
+        onDragStart={onDragStart}
+        onDragMove={onDragMove}
+        onDragEnd={onDragEnd}
+        onTransform={handleTransform}
+        onTransformEnd={handleTransformEnd}
+      >
+        {/* Invisible hit area so the whole bounding box is clickable/draggable */}
+        <Rect
+          ref={hitRectRef}
+          width={width}
+          height={height}
+          fill="transparent"
+          listening={true}
+        />
+        <Text
+          ref={textRef}
+          text={text}
+          width={width}
+          height={height}
+          fontSize={fontSize}
+          fontFamily={fontFamily}
+          fill={textColor}
+          align={textAlign}
+          verticalAlign="top"
+          fontStyle={getFontStyle(isBold || false, isItalic || false)}
+          textDecoration={isUnderline ? 'underline' : undefined}
+          padding={padding}
+          lineHeight={lineHeight}
+          letterSpacing={letterSpacing}
+          opacity={isEditing ? 0 : opacity}
+          listening={false}
+          wrap="word"
+        />
+        {/* Multi-select blue border */}
+        {isMultiSelect && isSelected && (
+          <Rect
+            width={width}
+            height={height}
+            stroke="#007bff"
+            strokeWidth={1.5}
+            listening={false}
+          />
+        )}
+      </Group>
+      {showTransformer && !isEditing && (
+        <Transformer
+          ref={transformerRef}
+          keepRatio={false}
+          anchorStroke="#007bff"
+          anchorFill="#ffffff"
+          anchorSize={8}
+          borderStroke="#007bff"
+          borderStrokeWidth={1.5}
+          rotateEnabled={true}
+          enabledAnchors={[
+            'top-left',
+            'top-right',
+            'bottom-left',
+            'bottom-right',
+            'middle-left',
+            'middle-right',
+            'top-center',
+            'bottom-center'
+          ]}
+          boundBoxFunc={(oldBox, newBox) => {
+            if (Math.abs(newBox.width) < 10 || Math.abs(newBox.height) < 10) {
+              return oldBox;
+            }
+            const anchor = transformerRef.current?.getActiveAnchor();
+            if (
+              anchor !== 'top-left' &&
+              anchor !== 'top-right' &&
+              anchor !== 'bottom-left' &&
+              anchor !== 'bottom-right'
+            ) {
+              return newBox;
+            }
+
+            // Corner drag: enforce uniform scale (keep aspect ratio).
+            const ratio = oldBox.width / oldBox.height;
+            const sx = newBox.width / oldBox.width;
+            const sy = newBox.height / oldBox.height;
+            const useWidth = Math.abs(sx) >= Math.abs(sy);
+
+            const w = useWidth ? newBox.width : newBox.height * ratio;
+            const h = useWidth ? newBox.width / ratio : newBox.height;
+
+            // The box origin (x,y) is the top-left of the unrotated rect.
+            // To keep the opposite corner fixed after resizing, compute
+            // its absolute position, then derive the new origin.
+            const rad = oldBox.rotation;
+            const cos = Math.cos(rad);
+            const sin = Math.sin(rad);
+
+            // Which local corner is anchored (opposite of dragged):
+            // 0 = left/top edge, 1 = right/bottom edge
+            const ax =
+              anchor === 'top-right' || anchor === 'bottom-right' ? 0 : 1;
+            const ay =
+              anchor === 'bottom-left' || anchor === 'bottom-right' ? 0 : 1;
+
+            // Anchored corner position (from old box)
+            const anchorAbsX =
+              oldBox.x + ax * oldBox.width * cos - ay * oldBox.height * sin;
+            const anchorAbsY =
+              oldBox.y + ax * oldBox.width * sin + ay * oldBox.height * cos;
+
+            // New origin so the anchored corner stays fixed
+            return {
+              ...newBox,
+              x: anchorAbsX - ax * w * cos + ay * h * sin,
+              y: anchorAbsY - ax * w * sin - ay * h * cos,
+              width: w,
+              height: h
+            };
+          }}
+        />
+      )}
+    </>
+  );
+};
+
+export default TextV2Node;
