+'use client';
+
+import { useCallback, useEffect, useState } from 'react';
+import { useTranslations } from 'next-intl';
+
+import { Label } from '@/components/ui/label';
+import { Input } from '@/components/ui/input';
+import { ScrollArea } from '@/components/ui/scroll-area';
+
+import { TextV2Object } from '../types';
+import InfoLayout from '../info-layout';
+
+import { ColorInput } from './color-input';
+import FontSelect from './text-form/font-select';
+import FontStyleSelect from './text-form/font-style-select';
+import TextAlignSelect from './text-form/text-align-select';
+
+type TextV2Property = keyof Pick<
+  TextV2Object,
+  | 'fontSize'
+  | 'fontFamily'
+  | 'textColor'
+  | 'isBold'
+  | 'isItalic'
+  | 'isUnderline'
+  | 'textAlign'
+>;
+
+type TextAlign = 'left' | 'center' | 'right';
+
+type EditingState = {
+  fontSize: number;
+  fontFamily: string;
+  textColor: string;
+  isBold: boolean;
+  isItalic: boolean;
+  isUnderline: boolean;
+  textAlign: TextAlign;
+};
+
+type TextV2InfoProps = {
+  textV2: TextV2Object;
+  parentPanelId: string | null;
+  onUpdateTextV2: (
+    textId: string,
+    updates: Partial<TextV2Object>,
+    panelId: string | null
+  ) => void;
+};
+
+export const TextV2Info = ({
+  textV2,
+  parentPanelId,
+  onUpdateTextV2
+}: TextV2InfoProps) => {
+  const t = useTranslations('Canvas.objectInfo.textV2Info');
+
+  const [editingState, setEditingState] = useState<EditingState>({
+    fontSize: textV2.fontSize,
+    fontFamily: textV2.fontFamily,
+    textColor: textV2.textColor,
+    isBold: textV2.isBold ?? false,
+    isItalic: textV2.isItalic ?? false,
+    isUnderline: textV2.isUnderline ?? false,
+    textAlign: textV2.textAlign ?? 'left'
+  });
+
+  const {
+    fontSize: editingFontSize,
+    fontFamily: editingFontFamily,
+    textColor: editingTextColor,
+    isBold,
+    isItalic,
+    isUnderline,
+    textAlign
+  } = editingState;
+
+  const handlePropertyChange = useCallback(
+    (property: TextV2Property, value: string | number | boolean) => {
+      let updates: Partial<TextV2Object> = {};
+
+      switch (property) {
+        case 'fontSize':
+          setEditingState((prev) => ({ ...prev, fontSize: value as number }));
+          updates = { fontSize: value as number };
+          break;
+        case 'fontFamily':
+          setEditingState((prev) => ({ ...prev, fontFamily: value as string }));
+          updates = { fontFamily: value as string };
+          break;
+        case 'textColor':
+          setEditingState((prev) => ({ ...prev, textColor: value as string }));
+          updates = { textColor: value as string };
+          break;
+        case 'isBold':
+          setEditingState((prev) => ({ ...prev, isBold: value as boolean }));
+          updates = { isBold: value as boolean };
+          break;
+        case 'isItalic':
+          setEditingState((prev) => ({ ...prev, isItalic: value as boolean }));
+          updates = { isItalic: value as boolean };
+          break;
+        case 'isUnderline':
+          setEditingState((prev) => ({
+            ...prev,
+            isUnderline: value as boolean
+          }));
+          updates = { isUnderline: value as boolean };
+          break;
+        case 'textAlign':
+          setEditingState((prev) => ({
+            ...prev,
+            textAlign: value as TextAlign
+          }));
+          updates = { textAlign: value as TextAlign };
+          break;
+      }
+
+      onUpdateTextV2(textV2.id, updates, parentPanelId);
+    },
+    [textV2.id, parentPanelId, onUpdateTextV2]
+  );
+
+  // Sync external changes
+  useEffect(() => {
+    setEditingState({
+      fontSize: textV2.fontSize,
+      fontFamily: textV2.fontFamily,
+      textColor: textV2.textColor,
+      isBold: textV2.isBold ?? false,
+      isItalic: textV2.isItalic ?? false,
+      isUnderline: textV2.isUnderline ?? false,
+      textAlign: textV2.textAlign ?? 'left'
+    });
+  }, [textV2]);
+
+  return (
+    <ScrollArea className="h-full">
+      <InfoLayout>
+        <div className="space-y-3 py-2">
+          {/* Font Family */}
+          <div className="space-y-1">
+            <Label className="text-xs">{t('fontFamily')}</Label>
+            <FontSelect
+              value={editingFontFamily}
+              onValueChange={(v) => handlePropertyChange('fontFamily', v)}
+            />
+          </div>
+
+          {/* Font Size */}
+          <div className="space-y-1">
+            <Label className="text-xs">{t('fontSize')}</Label>
+            <Input
+              type="number"
+              min={1}
+              max={200}
+              value={editingFontSize}
+              onChange={(e) =>
+                handlePropertyChange(
+                  'fontSize',
+                  parseInt(e.target.value, 10) || 1
+                )
+              }
+              className="h-8 text-sm"
+            />
+          </div>
+
+          {/* Text Color */}
+          <div className="space-y-1">
+            <Label className="text-xs">{t('textColor')}</Label>
+            <ColorInput
+              value={editingTextColor}
+              onChange={(v) => handlePropertyChange('textColor', v)}
+            />
+          </div>
+
+          {/* Text Alignment */}
+          <div className="space-y-1">
+            <Label className="text-xs">{t('textAlignment')}</Label>
+            <TextAlignSelect
+              textAlign={textAlign}
+              textOrientation="horizontal"
+              onValueChange={(v: string) =>
+                handlePropertyChange('textAlign', v)
+              }
+            />
+          </div>
+
+          {/* Font Style */}
+          <div className="space-y-1">
+            <Label className="text-xs">{t('fontStyle')}</Label>
+            <FontStyleSelect
+              isBold={isBold}
+              isItalic={isItalic}
+              isUnderline={isUnderline}
+              onValueChange={(values: string[]) => {
+                handlePropertyChange('isBold', values.includes('bold'));
+                handlePropertyChange('isItalic', values.includes('italic'));
+                handlePropertyChange(
+                  'isUnderline',
+                  values.includes('underline')
+                );
+              }}
+            />
+          </div>
+        </div>
+      </InfoLayout>
+    </ScrollArea>
+  );
+};
