new file mode 100644
index 0000000..8a29e26
--- /dev/null
+++ b/components/canvas/floating/FloatingTextV2Editor.tsx
@@ -0,0 +1,144 @@
+'use client';
+
+import { useCallback, useEffect, useRef } from 'react';
+
+import { useCanvasTransformStore } from '@/store/canvas-transform-store';
+import {
+  canvasToScreen,
+  getObjectBounds
+} from '@/utils/canvas/floating-element-position';
+
+import { TextV2Object } from '../types';
+
+type FloatingTextV2EditorProps = {
+  textV2: TextV2Object;
+  placeholder?: string;
+  onTextChange: (textId: string, text: string) => void;
+  onFinishEditing: () => void;
+};
+
+const FloatingTextV2Editor = ({
+  textV2,
+  placeholder,
+  onTextChange,
+  onFinishEditing
+}: FloatingTextV2EditorProps) => {
+  const containerRef = useRef<HTMLDivElement>(null);
+  const textareaRef = useRef<HTMLTextAreaElement>(null);
+
+  const position = useCanvasTransformStore((state) => state.position);
+  const scale = useCanvasTransformStore((state) => state.scale);
+
+  const updatePosition = useCallback(() => {
+    const container = containerRef.current;
+    if (!container) return;
+
+    const transform = { x: position.x, y: position.y, scale };
+    const bounds = getObjectBounds(textV2);
+    const screenPos = canvasToScreen({ x: bounds.x, y: bounds.y }, transform);
+
+    container.style.left = `${screenPos.x}px`;
+    container.style.top = `${screenPos.y}px`;
+    container.style.width = `${bounds.width * scale}px`;
+    container.style.height = `${bounds.height * scale}px`;
+    container.style.transform = `rotate(${textV2.rotation ?? 0}deg)`;
+    container.style.transformOrigin = 'top left';
+  }, [textV2, position.x, position.y, scale]);
+
+  useEffect(() => {
+    updatePosition();
+  }, [updatePosition]);
+
+  // Auto-focus on mount — delayed so the browser finishes processing the
+  // mousedown/mouseup that created this editor before we steal focus.
+  // Without the delay, mouseup on the canvas steals focus back and
+  // triggers onBlur → onFinishEditing immediately.
+  useEffect(() => {
+    const timer = requestAnimationFrame(() => {
+      const textarea = textareaRef.current;
+      if (!textarea) return;
+
+      textarea.focus();
+      // Place cursor at end
+      textarea.selectionStart = textarea.value.length;
+      textarea.selectionEnd = textarea.value.length;
+    });
+    return () => cancelAnimationFrame(timer);
+  }, []);
+
+  const {
+    fontSize,
+    fontFamily,
+    textColor,
+    textAlign = 'left',
+    isBold,
+    isItalic,
+    isUnderline,
+    padding = 4,
+    lineHeight = 1.2,
+    letterSpacing = 0
+  } = textV2;
+
+  const scaledFontSize = fontSize * scale;
+  const scaledPadding = padding * scale;
+  const scaledLetterSpacing = letterSpacing * scale;
+  // Compensate for browser textarea's built-in top offset (baseline shift)
+  // This offset scales proportionally with the font size
+  const topOffset = -2 + scaledFontSize * -0.05;
+
+  return (
+    <div
+      ref={containerRef}
+      style={{
+        position: 'fixed',
+        left: -9999,
+        top: -9999,
+        zIndex: 1000,
+        pointerEvents: 'auto'
+      }}
+      onMouseDown={(e) => e.stopPropagation()}
+    >
+      <textarea
+        ref={textareaRef}
+        value={textV2.text}
+        placeholder={placeholder}
+        onChange={(e) => onTextChange(textV2.id, e.target.value)}
+        onBlur={onFinishEditing}
+        onKeyDown={(e) => {
+          // Prevent canvas shortcuts from firing while typing
+          e.stopPropagation();
+          if (e.key === 'Escape') {
+            e.preventDefault();
+            onFinishEditing();
+          }
+        }}
+        style={{
+          width: 'calc(100% + 4px)',
+          height: 'calc(100% + 4px)',
+          margin: `${topOffset}px -2px -2px -2px`,
+          resize: 'none',
+          border: '2px solid #007bff',
+          borderRadius: 0,
+          outline: 'none',
+          background: 'transparent',
+          overflow: 'hidden',
+          boxSizing: 'border-box',
+          // Match Konva text styling
+          fontSize: `${scaledFontSize}px`,
+          fontFamily,
+          color: textColor,
+          textAlign: textAlign as React.CSSProperties['textAlign'],
+          fontWeight: isBold ? 'bold' : 'normal',
+          fontStyle: isItalic ? 'italic' : 'normal',
+          textDecoration: isUnderline ? 'underline' : 'none',
+          padding: `${scaledPadding}px`,
+          lineHeight,
+          letterSpacing: `${scaledLetterSpacing}px`,
+          caretColor: textColor
+        }}
+      />
+    </div>
+  );
+};
+
+export default FloatingTextV2Editor;
