+import { calculateTextV2TransformResult } from '@/utils/canvas/text-v2';
+
+/**
+ * Custom hook for handling textV2-related events on the canvas.
+ * Follows the same pattern as useCanvasTextEvents but with
+ * fontSize ↔ scale synchronization on transform end.
+ */
+export const useCanvasTextV2Events = () => {
+  const { canvasObjects, updateTempCanvasObjects, commitTempCanvasObjects } =
+    useHistoryState();
+  const isReadOnly = useCanvasStore((state) => state.isReadOnly);
+
+  /**
+   * Handle real-time TextV2 drag movement for floating UI updates.
+   * Mirrors handleImageDragMove — updates the image-drag-store so
+   * FloatingTextV2Toolbar and FloatingQuickActions follow the object.
+

